<?php
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();foreach(($_POST['qty']??[]) as $id=>$q){$q=(int)$q;if($q<=0)remove_cart($id);else $_SESSION['cart'][(int)$id]=min(99,$q);}}catch(Throwable $e){$_SESSION['flash']=$e->getMessage();}redirect('shop/cart');}
$items=[];$total=0;$c=cart();if($c){$marks=implode(',',array_fill(0,count($c),'?'));$s=db()->prepare("SELECT * FROM shop_products WHERE id IN ($marks)");$s->execute(array_keys($c));foreach($s->fetchAll() as $p){$p['qty']=$c[$p['id']];$p['subtotal']=$p['qty']*$p['price'];$total+=$p['subtotal'];$items[]=$p;}}page_header('سبد خرید','shop');
?>
<section class="shop-wrap"><div class="shell"><div class="heading"><div><p>YOUR BAG</p><h2>سبد خرید</h2></div><a href="<?=url('shop')?>">ادامه خرید ↗</a></div><?php if(!empty($_SESSION['flash'])):?><div class="notice"><?=e($_SESSION['flash']);unset($_SESSION['flash'])?></div><?php endif;?><?php if(!$items):?><div class="empty">سبد خرید شما خالی است.</div><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><table class="cart-table"><thead><tr><th>محصول</th><th>قیمت</th><th>تعداد</th><th>جمع</th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><?=e($p['name'])?></td><td><?=money($p['price'])?></td><td><input class="qty" name="qty[<?=$p['id']?>]" type="number" min="0" value="<?=$p['qty']?>"></td><td><?=money($p['subtotal'])?></td></tr><?php endforeach;?></tbody></table><div class="cart-total"><strong>جمع کل: <?=money($total)?></strong><div class="buttons"><button class="btn" type="submit">به‌روزرسانی</button><a class="btn btn-gold" href="<?=url('shop/checkout')?>">ادامه و تسویه حساب</a></div></div></form><?php endif;?></div></section>
<?php page_footer(); ?>
